#include<bits/stdc++.h>
using namespace std;
int a[111111];
vector<int>v[111111];
int md=-1,o;
bool vis[111111];
inline void dfs(int p,int d){
//	cout<<p<<" "<<d<<endl;
	if(d>md&&a[p]==1){
		md=d;
		o=p;
	}
	for(int i=0;i<v[p].size();i++){
		if(vis[v[p][i]]==0){
			vis[v[p][i]]=1;
			dfs(v[p][i],d+1);
			vis[v[p][i]]=0;
		} 
	}
}
inline void dfs1(int p,int d){
//	cout<<p<<" "<<d<<endl;
	if(d>md&&a[p]==1){
		md=d;
		o=p;
	}
	for(int i=0;i<v[p].size();i++){
		if(vis[v[p][i]]==0){
			vis[v[p][i]]=1;
			if(a[v[p][i]]==1){
				dfs1(v[p][i],d+1);	
			}else{
				dfs1(v[p][i],d);
			}
			
			vis[v[p][i]]=0;
		} 
	}
}
void abc(){
	int n,sum=0;
	cin>>n;
	for(int i=0;i<n;i++){
		v[i].clear();
	}
