		cin>>a[i];
		sum+=a[i];
	}
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
//	cout<<endl;
	memset(vis,0,sizeof(vis));
	vis[1]=1;
	dfs(1,0);
//	cout<<endl;
	memset(vis,0,sizeof(vis));
	vis[o]=1;
	md=0;
	dfs1(o,1);
//	cout<<md<<endl;
	if(md==sum){
		cout<<"Yes"<<endl;
	}else{
		cout<<"No"<<endl;
	}
}
